/* ===== V118: تفاصيل الطلب ===== */
function orderDetail(o){
  const ov=document.createElement('div'); ov.className='ov';
  const st=(STATUSES[o.status]||STATUSES.prep)[0], dt=new Date(o.ts);
  const when=dt.toLocaleDateString('ar-IQ-u-nu-latn',{weekday:'long',day:'numeric',month:'numeric',year:'numeric'})+'، '+dt.toLocaleTimeString('ar-IQ-u-nu-latn',{hour:'numeric',minute:'2-digit'});
  const row=(a,b,c)=>b===''||b==null?'':`<div class="od-r${c?' '+c:''}"><span>${a}</span><span>${b}</span></div>`;
  const items=(o.items||[]).map(i=>{ const n=i.name||'', kg=(n.match(/([\d.]+)\s*كغم/)||[])[1];
    return `<div class="od-it"><div><b>${i.qty} × ${esc(n.split(' — ')[0])}</b>${n.includes(' — ')?`<small>${esc(n.split(' — ').slice(1).join(' — '))}</small>`:''}</div><span>${fmt((+i.qty||0)*(+i.price||0))} د.ع${kg&&i.qty>0?`<small>${fmt(Math.round((+i.price||0)/kg))} للكيلو</small>`:''}</span></div>` }).join('');
  const s=o.stk||orderStock(o), stk=[];
  if(s.fishKg) stk.push(s.fishKg+' كغم سمك'); if(s.fishbox) stk.push(s.fishbox+' بوكس'); if(s.rice) stk.push(s.rice+' علبة تمن');
  if(s.torshi) stk.push(s.torshi+' طرشي'); if(s.mabooj) stk.push(s.mabooj+' معبوج'); if(s.tamur) stk.push(s.tamur+' تمر');
  ov.innerHTML=`<div class="dlg od-dlg" role="dialog" aria-modal="true">
    <div class="od-top"><div class="dlg-t" style="margin:0">طلب #${o.num}</div><span class="typechip">${TYPE_TXT[o.type]||''}</span><span class="od-st">${esc(st)}</span></div>
    <div class="od-sec">${row('الوقت',esc(when))}${row('الزبون',esc(o.name||''))}${row('التلفون',o.phone?`<span class="ltr">${esc(o.phone)}</span>`:'')}${row('العنوان',esc(o.addr||''))}${row('التسليم',esc(o.when||''))}${row('ملاحظة',esc(o.custNote||''))}</div>
    <div class="od-sec">${items||'<p class="note">ماكو أصناف</p>'}</div>
    <div class="od-sec">${row('قيمة الأكل',fmt(o.sub||0)+' د.ع')}${row('أجرة التوصيل',fmt(o.del||0)+' د.ع')}${o.dis?row('الخصم','− '+fmt(o.dis)+' د.ع','od-dis'):''}${row('المجموع',fmt(o.total||0)+' د.ع','od-tot')}</div>
    ${stk.length?`<div class="od-sec"><div class="od-r"><span>طلع من المخزن</span><span>${stk.join('، ')}</span></div>${o.stkBack?'<p class="note">رجع للمخزن بعد الإلغاء</p>':''}</div>`:''}
    <div class="dlg-act"><button class="btn-main" data-a="print">طباعة</button><button class="btn-ghost" data-a="x">سكّر</button></div></div>`;
  document.body.appendChild(ov);
  ov.addEventListener('click',e=>{ if(e.target===ov) ov.remove() });
  ov.querySelector('[data-a="x"]').addEventListener('click',()=>ov.remove());
  ov.querySelector('[data-a="print"]').addEventListener('click',()=>{ ov.remove(); printSticker(o) });
}
    d.querySelector('.oinfo').addEventListener('click',()=>orderDetail(o)); d.querySelector('.onum').addEventListener('click',()=>orderDetail(o));
