.orow .oinfo,.orow .onum{cursor:pointer}
.od-dlg{width:min(100%,560px);max-height:88vh;overflow:auto}
.od-top{display:flex;align-items:center;gap:10px;margin-bottom:12px}
.od-st{margin-inline-start:auto;font-size:13px;color:#9296A0}
.od-sec{border-top:1px solid var(--line2,#2a2c33);padding:10px 0;display:grid;gap:8px}
.od-r{display:flex;justify-content:space-between;gap:14px;font-size:15px}
.od-r span:first-child{color:#9296A0;flex:none}
.od-r span:last-child{text-align:left}
.od-it{display:flex;justify-content:space-between;gap:14px;font-size:15px}
.od-it small{display:block;color:#9296A0;font-size:12.5px;margin-top:2px;line-height:1.5}
.od-it>span{text-align:left;flex:none}
.od-dis span:last-child{color:#FF6B5E}
.od-tot{font-size:18px;font-weight:700}
